     1	using Microsoft.EntityFrameworkCore;
     2	using seed_b_backend.Api.Data;
     3	using seed_b_backend.Api.Dtos;
     4	
     5	namespace seed_b_backend.Api.Services;
     6	
     7	public class ProductQueryService(AppDbContext db)
     8	{
     9	    private const int PageSize = 20;
    10	
    11	    public async Task<PagedResultDto<ProductListItemDto>> GetProductsAsync(int page)
    12	    {
    13	        page = page < 1 ? 1 : page;
    14	
    15	        var query = db.Products.Include(p => p.Subcategory);
    16	
    17	        var totalCount = await query.CountAsync();
    18	
    19	        var items = await query
    20	            .OrderBy(p => p.Name)
    21	            .Skip((page - 1) * PageSize)
    22	            .Take(PageSize)
    23	            .Select(p => new ProductListItemDto(
    24	                p.Id,
    25	                p.Name,
    26	                p.Subcategory!.Name,
    27	                p.Offers.Min(o => o.Price)))
    28	            .ToListAsync();
    29	
    30	        var totalPages = (int)Math.Ceiling(totalCount / (double)PageSize);
    31	
    32	        return new PagedResultDto<ProductListItemDto>(items, page, PageSize, totalCount, totalPages);
    33	    }
    34	}
